         }]);
         showToast('经文已分享到聊天室');
      } else {
         showToast(`已切换至 ${book} 第${chapter}章`);
      }
    };

    const handleUserClick = (participant: Participant) => {
        if (participant.id === 'me' || participant.id === 'pastor') return; 
        if (!canManage) return;
        setSelectedParticipant(participant);
        setShowUserManageModal(true);
