                showToast(p.role === 'speaker' ? `已将 ${p.name} 移至观众席` : `已邀请 ${p.name} 上麦`);
                return { ...p, role: newRole };
            }
            return p;
        }));
        if (action === 'kick') {
            setParticipants(prev => prev.filter(p => p.id !== selectedParticipant.id));
            showToast(`已将 ${selectedParticipant.name} 踢出房间`);
