                >
                    发送
                </button>
                <button 
                    onClick={() => {
                        setActiveCommentPostId(null);
                        setCommentInput("");
                    }}
                    className="p-1.5 text-slate-400 hover:text-slate-600 transition-colors shrink-0 mb-1"
                >
                    <X size={22} strokeWidth={2.5} />
                </button>
            </div>,
            document.body
        )}
    </div>
  );
};

