const ChatView: React.FC<ChatViewProps> = ({ 
  onBack, 
  initialChatId, 
  onPrivateChat, 
  conversations = INITIAL_CONVERSATIONS, 
  onToggleMute, 
  onTogglePin 
}) => {
  const [activeChatId, setActiveChatId] = useState<string | null>(initialChatId || null);
  const [messages, setMessages] = useState<Record<string, Message[]>>(() => {
    try {
        const saved = localStorage.getItem('amas_chat_messages');
        return saved ? JSON.parse(saved) : INITIAL_MESSAGES;
    } catch (e) { return INITIAL_MESSAGES; }
  });
  const [inputText, setInputText] = useState("");
  const [showChatDetail, setShowChatDetail] = useState(false);
  const [searchMode, setSearchMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => { if (initialChatId) setActiveChatId(initialChatId); }, [initialChatId]);
  useEffect(() => { localStorage.setItem('amas_chat_messages', JSON.stringify(messages)); }, [messages]);

  const activeConv = conversations.find(c => c.id === activeChatId) || conversations[0] || INITIAL_CONVERSATIONS[0];
  const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];
  const filteredMessages = searchQuery.trim() ? currentMessages.filter(m => m.text?.toLowerCase().includes(searchQuery.toLowerCase())) : currentMessages;

  const sendMessage = (msgData: Partial<Message>) => {
    if (!activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      isMe: true,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      status: 'sent',
      type: 'text',
      ...msgData
    };
    setMessages(prev => ({ ...prev, [activeChatId]: [...(prev[activeChatId] || []), newMessage] }));
    setInputText("");
  };

  const handleClearHistory = (id: string) => {
      if(confirm("确定要清空与该校友的本地聊天记录吗？此操作无法撤销。")) {
          setMessages(prev => ({ ...prev, [id]: [] }));
          setShowChatDetail(false);
      }
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [currentMessages]);

  return (
    <div className="flex flex-col h-screen bg-[#f1f3f5] relative w-full overflow-hidden">
        {showChatDetail && (
            activeConv.isGroup ? (
                <GroupDetailView 
                    conv={activeConv} 
                    messages={currentMessages} 
                    onBack={() => setShowChatDetail(false)} 
                    onClearHistory={() => handleClearHistory(activeConv.id)} 
                    onSearchRecords={() => { setSearchMode(true); setShowChatDetail(false); }}
                    onToggleMute={() => onToggleMute?.(activeConv.id)}
                    onTogglePin={() => onTogglePin?.(activeConv.id)}
                    onUpdateMessages={(notice) => {
                         if(!activeChatId) return;
                         setMessages(prev => ({
                             ...prev,
                             [activeChatId]: [...(prev[activeChatId] || []), {
                                 id: Date.now().toString(),
                                 isMe: true,
                                 time: '刚刚',
                                 status: 'sent',
                                 type: 'notice',
                                 text: notice
                             }]
                         }));
                    }}
                />
            ) : (
                <DirectDetailView 
                    conv={activeConv} 
                    messages={currentMessages}
                    onBack={() => setShowChatDetail(false)} 
                    onClearHistory={() => handleClearHistory(activeConv.id)} 
                    onSearchRecords={() => { setSearchMode(true); setShowChatDetail(false); }}
                    onToggleMute={() => onToggleMute?.(activeConv.id)}
                    onTogglePin={() => onTogglePin?.(activeConv.id)}
                    onPrivateChat={(u) => { setShowChatDetail(false); onPrivateChat?.(u); }}
                />
            )
        )}

        {/* --- Header --- */}
        <div className="bg-white/90 backdrop-blur-md border-b border-slate-200 px-4 py-3 flex items-center justify-between pt-safe-top shrink-0 shadow-sm z-10">
            {!searchMode ? (
                <>
                <div className="flex items-center">
                    <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 text-slate-800 transition mr-1"><ChevronLeft size={24} /></button>
                    <div className="flex items-center" onClick={() => setShowChatDetail(true)}>
                        <img src={activeConv.userAvatar} className="w-10 h-10 rounded-full mr-3 object-cover shadow-sm border border-slate-100" />
                        <div>
                            <h2 className="text-sm font-bold text-slate-900 leading-tight">{activeConv.userName}</h2>
                            <p className="text-[10px] text-emerald-500 font-medium">{activeConv.isOnline ? '在线' : '离线'}</p>
                        </div>
                    </div>
                </div>
                <button onClick={() => setShowChatDetail(true)} className="p-2 text-slate-500 hover:text-slate-800 transition"><MoreVertical size={20}/></button>
                </>
            ) : (
                <div className="flex items-center w-full">
                    <Search size={18} className="text-slate-400 mr-2" />
                    <input 
                      className="flex-1 bg-transparent text-sm outline-none" 
                      placeholder="搜索聊天记录..." 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      autoFocus
                    />
                    <button onClick={() => { setSearchMode(false); setSearchQuery(""); }} className="text-blue-600 text-sm font-bold ml-2">取消</button>
                </div>
            )}
        </div>

        {/* --- Messages Area --- */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth scrollbar-hide">
            {filteredMessages.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full opacity-30">
                    <ShieldCheck size={48} className="mb-2" />
                    <p className="text-xs font-bold uppercase tracking-widest">AMAS 安全加密聊天</p>
                </div>
            ) : (
                filteredMessages.map((msg) => (
                    <div key={msg.id} className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                        <div className={`max-w-[75%] rounded-2xl px-4 py-2 text-sm shadow-sm ${msg.isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none'}`}>
                            {msg.text}
                            <div className={`text-[9px] mt-1 text-right ${msg.isMe ? 'text-blue-100' : 'text-slate-400'}`}>
                                {msg.time}
                            </div>
                        </div>
                    </div>
                ))
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* --- Input Area --- */}
        <div className="bg-white border-t border-slate-200 p-3 pb-[calc(env(safe-area-inset-bottom)+8px)] flex items-center space-x-2 shrink-0">
            <button className="p-2 text-slate-400 hover:text-slate-600"><Plus size={24}/></button>
            <div className="flex-1 bg-slate-100 rounded-full px-4 py-2 border border-slate-200 focus-within:bg-white focus-within:ring-2 focus-within:ring-blue-100 transition-all">
                <input 
                  className="w-full bg-transparent outline-none text-sm" 
                  placeholder="发送消息..." 
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && sendMessage({ text: inputText })}
                />
            </div>
            {inputText.trim() ? (
                <button onClick={() => sendMessage({ text: inputText })} className="p-2 bg-blue-600 text-white rounded-full shadow-md active:scale-95 transition-all"><Send size={18}/></button>
            ) : (
                <button className="p-2 text-slate-400"><ImageIcon size={24}/></button>
            )}
        </div>
    </div>
  );
};

export default ChatView;

