const ChatView: React.FC<ChatViewProps> = ({ 
  onBack, 
  initialChatId, 
  onPrivateChat, 
  conversations = INITIAL_CONVERSATIONS, 
  onToggleMute, 
  onTogglePin 
}) => {
  const [activeChatId, setActiveChatId] = useState<string | null>(initialChatId || null);
  const [messages, setMessages] = useState<Record<string, Message[]>>(() => {
    try {
        const saved = localStorage.getItem('amas_chat_messages');
        return saved ? JSON.parse(saved) : INITIAL_MESSAGES;
    } catch (e) { return INITIAL_MESSAGES; }
  });
  const [inputText, setInputText] = useState("");
  const [showChatDetail, setShowChatDetail] = useState(false);
  const [searchMode, setSearchMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => { if (initialChatId) setActiveChatId(initialChatId); }, [initialChatId]);
  useEffect(() => { localStorage.setItem('amas_chat_messages', JSON.stringify(messages)); }, [messages]);

  const activeConv = conversations.find(c => c.id === activeChatId) || conversations[0] || INITIAL_CONVERSATIONS[0];
  const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];
  const filteredMessages = searchQuery.trim() ? currentMessages.filter(m => m.text?.toLowerCase().includes(searchQuery.toLowerCase())) : currentMessages;

  const sendMessage = (msgData: Partial<Message>) => {
    if (!activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      isMe: true,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      status: 'sent',
      type: 'text',
      ...msgData
    };
    setMessages(prev => ({ ...prev, [activeChatId]: [...(prev[activeChatId] || []), newMessage] }));
    setInputText("");
  };

  const handleClearHistory = (id: string) => {
      if(confirm("确定要清空与该校友的本地聊天记录吗？此操作无法撤销。")) {
          setMessages(prev => ({ ...prev, [id]: [] }));
          setShowChatDetail(false);
      }
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [currentMessages]);

  return (
    <div className="flex flex-col h-screen bg-[#f1f3f5] relative w-full overflow-hidden font-sans">
        {showChatDetail && (
            activeConv.isGroup ? (
                <GroupDetailView 
                    conv={activeConv} 
                    onBack={() => setShowChatDetail(false)} 
                    onClearHistory={() => handleClearHistory(activeConv.id)} 
                    onToggleMute={() => onToggleMute?.(activeConv.id)}
                    onTogglePin={() => onTogglePin?.(activeConv.id)}
                />
            ) : (
                <DirectDetailView 
                    conv={activeConv} 
                    onBack={() => setShowChatDetail(false)} 
                    onClearHistory={() => handleClearHistory(activeConv.id)} 
                    onToggleMute={() => onToggleMute?.(activeConv.id)}
                    onTogglePin={() => onTogglePin?.(activeConv.id)}
                />
            )
        )}

        {/* --- Header --- */}
        <div className="bg-white/95 backdrop-blur-md border-b border-slate-200 px-4 py-3 flex items-center justify-between pt-safe-top shrink-0 shadow-sm z-10">
            {!searchMode ? (
                <>
                <div className="flex items-center">
                    <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 text-slate-800 transition mr-1"><ChevronLeft size={24} /></button>
                    <div className="flex items-center" onClick={() => setShowChatDetail(true)}>
                        <img src={activeConv.userAvatar} className="w-10 h-10 rounded-xl mr-3 object-cover shadow-sm border border-slate-100" />
                        <div>
                            <div className="flex items-center space-x-1.5">
                              <h2 className="text-[15px] font-bold text-slate-900 leading-tight">{activeConv.userName}</h2>
                              {activeConv.isMuted && <BellOff size={10} className="text-slate-300" />}
                            </div>
                            <p className="text-[10px] text-emerald-500 font-bold uppercase tracking-tight">{activeConv.isOnline ? '● 在线 Online' : '离线 Offline'}</p>
                        </div>
                    </div>
                </div>
                <button onClick={() => setShowChatDetail(true)} className="p-2 text-slate-500 hover:text-slate-800 transition"><MoreVertical size={20}/></button>
                </>
            ) : (
                <div className="flex items-center w-full">
                    <Search size={18} className="text-slate-400 mr-2" />
                    <input 
                      className="flex-1 bg-transparent text-sm outline-none" 
                      placeholder="搜索聊天记录..." 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      autoFocus
                    />
                    <button onClick={() => { setSearchMode(false); setSearchQuery(""); }} className="text-blue-600 text-sm font-bold ml-2">取消</button>
                </div>
            )}
        </div>

        {/* --- Messages Area --- */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth scrollbar-hide bg-slate-50/50">
            {filteredMessages.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full opacity-20">
                    <ShieldCheck size={64} className="mb-4" />
                    <p className="text-[10px] font-black uppercase tracking-[0.3em]">AMAS 端到端加密通讯</p>
                </div>
            ) : (
                filteredMessages.map((msg) => (
                    <div key={msg.id} className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                        <div className={`flex flex-col ${msg.isMe ? 'items-end' : 'items-start'} max-w-[80%]`}>
                          <div className={`rounded-2xl px-4 py-2.5 text-[15px] shadow-sm leading-relaxed ${msg.isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
                              {msg.text}
                          </div>
                          <div className={`text-[9px] mt-1.5 font-bold opacity-50 px-1 ${msg.isMe ? 'text-blue-900' : 'text-slate-400'}`}>
                              {msg.time}
                          </div>
                        </div>
                    </div>
                ))
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* --- Input Area --- */}
        <div className="bg-white border-t border-slate-200 p-3 pb-[calc(env(safe-area-inset-bottom)+8px)] flex items-center space-x-2 shrink-0">
            <button className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Plus size={24}/></button>
            <div className="flex-1 bg-slate-100 rounded-2xl px-4 py-2 border border-slate-100 focus-within:bg-white focus-within:ring-2 focus-within:ring-blue-100 transition-all">
                <input 
                  className="w-full bg-transparent outline-none text-sm py-1" 
                  placeholder="说点什么吧..." 
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && inputText.trim() && sendMessage({ text: inputText })}
                />
            </div>
            {inputText.trim() ? (
                <button onClick={() => sendMessage({ text: inputText })} className="p-2 bg-blue-600 text-white rounded-xl shadow-md active:scale-95 transition-all"><Send size={18}/></button>
            ) : (
                <button className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><ImageIcon size={24}/></button>
            )}
        </div>
    </div>
  );
};

export default ChatView;

