                              {/* Bubble Tail */}
                              <div className={`absolute top-3 w-2 h-2 rotate-45 ${msg.isMe ? '-right-1 bg-[#95ec69]' : '-left-1 bg-white'}`} />
                              <div className="relative z-10">{msg.text}</div>
                          </div>
                          <div className={`text-[10px] mt-2 font-medium opacity-30 px-1 ${msg.isMe ? 'text-slate-900' : 'text-slate-400'}`}>
                              {msg.time}
                          </div>
                        </div>
                    </div>
                ))
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* --- Input Area --- */}
        <div className="bg-[#f7f7f7] border-t border-slate-200 p-3 pb-[calc(env(safe-area-inset-bottom)+8px)] flex items-center space-x-2 shrink-0">
