           <UserProfileModal 
              user={viewingProfile} 
              onClose={() => setViewingProfile(null)} 
              onChat={(id) => {
                 setViewingProfile(null);
                 setShowChatDetail(false);
                 setActiveChatId(id);
              }}
              onViewFeed={(id) => {}}
           />
        )}

        {showChatDetail && (
            activeConv.isGroup ? (
                <GroupDetailView 
                    conv={activeConv} 
                    onBack={() => setShowChatDetail(false)} 
                    onClearHistory={() => handleClearHistory(activeConv.id)} 
                    onToggleMute={() => onToggleMute?.(activeConv.id)}
                    onTogglePin={() => onTogglePin?.(activeConv.id)}
                    onViewMember={setViewingProfile}
                />
            ) : (
                <DirectDetailView 
                    conv={activeConv} 
                    onBack={() => setShowChatDetail(false)} 
                    onClearHistory={() => handleClearHistory(activeConv.id)} 
                    onToggleMute={() => onToggleMute?.(activeConv.id)}
                    onTogglePin={() => onTogglePin?.(activeConv.id)}
                    onViewMember={setViewingProfile}
                />
            )
        )}

        {/* --- Header --- */}
        <div className="bg-[#ededed]/95 backdrop-blur-md border-b border-slate-200 px-4 py-3 flex items-center justify-between pt-safe-top shrink-0 shadow-sm z-10">
