                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && inputText.trim() && sendMessage({ text: inputText })}
                />
            </div>
            {inputText.trim() ? (
                <button onClick={() => sendMessage({ text: inputText })} className="p-2 bg-[#07c160] text-white rounded-[6px] shadow-sm active:opacity-80 transition-all font-bold text-sm px-4 h-[40px]">发送</button>
            ) : (
                <button className="p-2 text-slate-800 hover:bg-black/5 rounded-full transition-colors"><ImageIcon size={24}/></button>
            )}
        </div>
    </div>
  );
};

