  const feedCoverInputRef = useRef<HTMLInputElement>(null);
  const handleFeedCoverChange = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) { const reader = new FileReader(); reader.onload = (event) => { const result = event.target?.result as string; setFeedCoverImage(result); try { localStorage.setItem('amas_feed_cover', result); } catch (e) { console.error("Storage full"); } }; reader.readAsDataURL(e.target.files[0]); } };

  const [prayerRequests, setPrayerRequests] = useState([ { id: '1', title: '为世界和平祷告', content: '求主止息各地的战争与纷争，赐下平安在地上。', count: 128, timestamp: '刚刚更新', isPraying: false }, { id: '2', title: '为神学院的发展', content: '愿神预备更多的师资与资源，造就合用的工人。', count: 85, timestamp: '刚刚更新', isPraying: false }, { id: '3', title: '为未得之民', content: '求庄稼的主打发工人出去，收他的庄稼。', count: 256, timestamp: '刚刚更新', isPraying: false }, ]);

  useEffect(() => { setActiveTab(initialTab); if(initialTab === 'directory') setDirectoryTab('messages'); }, [initialTab]);
  const showToast = (msg: string) => { setShowToastMsg(msg); setTimeout(() => setShowToastMsg(null), 3000); };

  const toggleExpand = (id: string) => setExpandedId(expandedId === id ? null : id);

  const handleCreateRoom = (name: string, type: RoomType, password?: string) => { const config = THEME_CONFIGS[type]; const newRoom: Room = { id: `custom-${Date.now()}`, type: type, label: name, icon: config.icon, color: config.color, bg: config.bg, desc: config.desc, action: 'voice', participants: 1, isCustom: true, hostId: 'me', password: password }; setMyRoom(newRoom); setActiveVoiceRoom(newRoom); setIsRoomMinimized(false); setShowCreateRoom(false); showToast("房间创建成功！"); };
  const handleCreateGroupChat = (name: string, members: string[]) => { const newGroupId = `g-${Date.now()}`; const newGroup: Conversation = { id: newGroupId, userId: newGroupId, userName: name, userAvatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=random&color=fff`, isOnline: false, lastMessage: '群组已创建，开始聊天吧', time: '刚刚', unread: 0, role: 'Group', isGroup: true, isMuted: false, isPinned: false }; setConversations([newGroup, ...conversations]); try { const savedGroupsStr = localStorage.getItem('amas_custom_groups'); const savedGroups: Conversation[] = savedGroupsStr ? JSON.parse(savedGroupsStr) : []; savedGroups.push(newGroup); localStorage.setItem('amas_custom_groups', JSON.stringify(savedGroups)); } catch (e) { console.error("Failed to save group", e); } setShowCreateGroup(false); showToast(`群组 "${name}" 创建成功`); if (directoryTab !== 'groups') { setDirectoryTab('groups'); } };
  const handleJoinRoom = (room: Room) => { if (room.isCustom && room.hostId === 'me') { setActiveVoiceRoom(room); setIsRoomMinimized(false); return; } if (room.password) { setPendingRoom(room); setInputPassword(""); setShowPasswordPrompt(true); } else { setActiveVoiceRoom(room); setIsRoomMinimized(false); } };
  const handleConfirmPassword = () => { if (pendingRoom && inputPassword === pendingRoom.password) { setActiveVoiceRoom(pendingRoom); setIsRoomMinimized(false); setShowPasswordPrompt(false); setPendingRoom(null); showToast("密码验证成功"); } else { showToast("密码错误，请重试"); } };
  const handlePrayClick = (id: string) => { setPrayerRequests(prev => prev.map(req => { if (req.id === id) { return { ...req, count: req.isPraying ? req.count - 1 : req.count + 1, isPraying: !req.isPraying }; } return req; })); const req = prayerRequests.find(r => r.id === id); if (req && !req.isPraying) { showToast("已参与代祷"); } };
  const handleShareToFeed = (room: Room, comment: string) => { const newPost: CommunityPost = { id: `share-${Date.now()}`, userId: 'me', userName: MOCK_USER.name, userAvatar: MOCK_USER.avatar, userRole: MOCK_USER.degree, content: comment || `邀请大家来【${room.label}】一起交通！`, timestamp: '刚刚', likes: 0, comments: 0, likedByMe: false, likedByUsers: [], category: 'share', connectionStatus: 'none', sharedRoom: room }; setPosts([newPost, ...posts]); showToast("已分享到校友圈"); };
  const handleUpdateRoom = (updatedRoom: Room) => { if(myRoom && updatedRoom.id === myRoom.id) { setMyRoom(updatedRoom); } setActiveVoiceRoom(updatedRoom); };
  const handleEndRoom = () => { setMyRoom(null); setActiveVoiceRoom(null); showToast("房间已结束"); };
  const handleCreatePost = (content: string, images: string[], linkedCourseId?: string) => { const newPost: CommunityPost = { id: `post-${Date.now()}`, userId: 'me', userName: MOCK_USER.name, userAvatar: MOCK_USER.avatar, userRole: MOCK_USER.degree, content: content, images: images, timestamp: '刚刚', likes: 0, comments: 0, likedByMe: false, likedByUsers: [], category: 'general', connectionStatus: 'none', linkedCourseId: linkedCourseId }; setPosts([newPost, ...posts]); setShowCreateMoment(false); showToast("发布成功！"); };
  const handleLikePost = (postId: string) => { setPosts(posts.map(post => { if (post.id === postId) { const isLiked = post.likedByMe; let newLikers = post.likedByUsers || []; if (isLiked) { newLikers = newLikers.filter(u => u.id !== 'me'); } else { newLikers = [{ id: 'me', name: MOCK_USER.name, avatar: MOCK_USER.avatar }, ...newLikers]; } return { ...post, likes: newLikers.length, likedByMe: !isLiked, likedByUsers: newLikers }; } return post; })); };
  const handleSharePost = (target: 'copy' | 'chat', selectedIds?: string[]) => { if (target === 'copy') { navigator.clipboard.writeText(`看这个帖子: ${postToShare?.content.substring(0, 20)}...`); showToast("链接已复制"); } else if (target === 'chat' && selectedIds && postToShare) { showToast(`已发送给 ${selectedIds.length} 个会话`); } setPostToShare(null); };
  const handleCommentEmojiClick = (emoji: string) => { setCommentInput(prev => prev + emoji); };
  const handleCommentSubmit = (postId: string) => { if (!commentInput.trim()) return; setPosts(posts.map(post => { if (post.id === postId) { const newComment: Comment = { id: `c-${Date.now()}`, userId: 'me', userName: MOCK_USER.name, content: commentInput, userAvatar: MOCK_USER.avatar, userRole: MOCK_USER.degree }; return { ...post, comments: post.comments + 1, commentList: [...(post.commentList || []), newComment] }; } return post; })); setCommentInput(""); setActiveCommentPostId(null); setShowCommentEmojiPicker(false); showToast("评论已发送"); };
  const handleDeletePost = (postId: string) => { if (confirm("确定要删除这条动态吗？")) { setPosts(posts.filter(p => p.id !== postId)); showToast("动态已删除"); } };
  const handleMarkAllNotificationsAsRead = () => { setNotifications(prev => prev.map(n => ({ ...n, isRead: true }))); showToast("已全部标为已读"); };
  const unreadNotifications = notifications.some(n => !n.isRead);
  const Equalizer = () => (<div className="flex space-x-0.5 items-end h-3"><div className="w-0.5 bg-blue-500 h-1.5 animate-pulse"></div><div className="w-0.5 bg-blue-500 h-3 animate-pulse delay-75"></div><div className="w-0.5 bg-blue-500 h-2 animate-pulse delay-150"></div></div>);
  const filteredConversations = conversations.filter(c => c.userName.toLowerCase().includes(searchQuery.toLowerCase()) || c.lastMessage.toLowerCase().includes(searchQuery.toLowerCase()));
  const filteredContacts = contacts.filter(c => c.name.toLowerCase().includes(searchQuery.toLowerCase()) || c.role.toLowerCase().includes(searchQuery.toLowerCase()));
  const getLinkedCourse = (id?: string) => MOCK_COURSES.find(c => c.id === id);

  return (
    <div className="min-h-screen bg-slate-50 pb-24 relative animate-fade-in">
        {/* Global UI Components */}
        {showToastMsg && (
          <div className="fixed top-20 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-4 py-2 rounded-full text-xs font-bold shadow-lg z-[100] animate-fade-in flex items-center">
