               {[
                  "培养通过神的话语和圣灵的能力得到装备的牧会者和宣教士。",
                  "在亚洲国家差遣通过神的话语和圣灵的能力得到装备的宣教士。",
                  "在亚洲国家建立重视圣经和实践的神学校，培养该国家本地的牧会者。"
               ].map((v, i) => (
                  <div key={i} className="flex items-start">
                     <span className="text-blue-100 font-black mr-4 text-2xl leading-none mt-0.5 select-none">{i+1}</span>
                     <p className="text-[13px] font-bold leading-relaxed text-slate-500 text-justify">{v}</p>
                  </div>
               ))}
            </div>
         </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { Home, BookOpen, Library, User, Users } from 'lucide-react';
import { ViewState } from '../types';

interface NavigationProps {
  currentView: ViewState;
  onViewChange: (view: ViewState) => void;
  unreadCount?: number;
}

const Navigation: React.FC<NavigationProps> = ({ currentView, onViewChange, unreadCount = 0 }) => {
  const navItems = [
    { id: ViewState.HOME, icon: Home, label: '首页' },
    { id: ViewState.COURSES, icon: BookOpen, label: '课程' },
    { id: ViewState.COMMUNITY, icon: Users, label: '校友圈' },
    { id: ViewState.LIBRARY, icon: Library, label: '图书馆' },
    { id: ViewState.PROFILE, icon: User, label: '我的' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 w-full bg-white/95 backdrop-blur-md border-t border-slate-100 pb-safe-area shadow-[0_-10px_30px_rgba(0,0,0,0.02)] z-[1000]">
      <div className="flex justify-around items-center h-20 max-w-lg mx-auto px-2">
        {navItems.map((item) => {
          const isActive = currentView === item.id;
          const Icon = item.icon;
          return (
            <button
              key={item.id}
              onClick={() => onViewChange(item.id)}
              className={`flex flex-col items-center justify-center w-full h-full space-y-1.5 transition-all duration-300 relative ${
                isActive ? 'text-blue-900' : 'text-slate-300 hover:text-slate-400'
              }`}
            >
              {isActive && (
                <div className="absolute top-0 w-8 h-1 bg-blue-900 rounded-b-full shadow-sm animate-fade-in"></div>
              )}
              <div className="relative">
                <Icon
                  size={24}
                  strokeWidth={isActive ? 3 : 2}
                  className={isActive ? 'scale-110 drop-shadow-sm' : ''}
                />
                {item.id === ViewState.COMMUNITY && unreadCount > 0 && (
                  <span className="absolute -top-1.5 -right-1.5 min-w-[18px] h-[18px] flex items-center justify-center bg-rose-500 text-white text-[9px] font-black rounded-full border-2 border-white shadow-sm px-1 animate-scale-in">
                    {unreadCount > 99 ? '99+' : unreadCount}
                  </span>
                )}
              </div>
              <span className={`text-[10px] font-black tracking-tight ${isActive ? 'text-blue-900' : 'text-slate-400'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default Navigation;

import React, { useState } from 'react';
import { ChevronLeft, Bell, Search, Plus, Edit2, Trash2, X, Settings, ChevronDown, ChevronUp, AlertOctagon, Info, AlertTriangle } from 'lucide-react';
import { NewsItem } from '../types';
import { MOCK_USER } from '../constants';

interface AnnouncementsViewProps {
  onBack: () => void;
  newsItems: NewsItem[];
  setNewsItems: (items: NewsItem[]) => void;
}

const AnnouncementsView: React.FC<AnnouncementsViewProps> = ({ onBack, newsItems, setNewsItems }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showEditModal, setShowEditModal] = useState(false);
  const [isManageMode, setIsManageMode] = useState(false);
  const [editingItem, setEditingItem] = useState<NewsItem | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deletingItemId, setDeletingItemId] = useState<string | null>(null);

  const [newsForm, setNewsForm] = useState({ 
    title: '', 
    date: '', 
    type: 'Notice' as 'Notice' | 'Event' | 'Urgent',
    content: '' 
  });

  const isAdmin = MOCK_USER.role === 'admin';

  const filteredNews = newsItems.filter(item => 
    item.title.toLowerCase().includes(searchQuery.toLowerCase())
  ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const handleAddEditNews = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newsForm.title || !newsForm.date) return;

    if (editingItem) {
      setNewsItems(newsItems.map(item => item.id === editingItem.id ? { ...editingItem, ...newsForm } : item));
    } else {
      const newItem: NewsItem = {
        id: `news-${Date.now()}`,
        ...newsForm
      };
      setNewsItems([newItem, ...newsItems]);
    }
    setShowEditModal(false);
    setEditingItem(null);
    setNewsForm({ title: '', date: '', type: 'Notice', content: '' });
  };

  const initiateDelete = (id: string) => {
    setDeletingItemId(id);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = () => {
    if (deletingItemId) {
      setNewsItems(newsItems.filter(item => item.id !== deletingItemId));
      setShowDeleteConfirm(false);
      setDeletingItemId(null);
    }
  };

  const startEdit = (item: NewsItem) => {
    setEditingItem(item);
    setNewsForm({ title: item.title, date: item.date, type: item.type, content: item.content || '' });
    setShowEditModal(true);
  };

  const startAdd = () => {
    setEditingItem(null);
    setNewsForm({ title: '', date: new Date().toISOString().split('T')[0], type: 'Notice', content: '' });
    setShowEditModal(true);
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const getTypeText = (type: string) => {
    switch (type) {
      case 'Urgent': return '紧急';
      case 'Event': return '活动';
      default: return '通知';
    }
  };

  const getTypeStyles = (type: string) => {
    switch (type) {
      case 'Urgent':
        return {
          container: 'border-rose-100 bg-white',
          iconContainer: 'bg-rose-50 text-rose-500 shadow-[0_4px_12px_rgba(244,63,94,0.15)]',
          badge: 'bg-rose-500 text-white border-rose-600',
          title: 'text-rose-900',
        };
      case 'Event':
        return {
          container: 'border-slate-100 bg-white',
          iconContainer: 'bg-amber-50 text-amber-500 shadow-[0_4px_12px_rgba(245,158,11,0.1)]',
          badge: 'bg-amber-500 text-white border-amber-600',
          title: 'text-slate-900',
        };
      default:
        return {
          container: 'border-slate-100 bg-white',
          iconContainer: 'bg-blue-50 text-blue-500 shadow-[0_4px_12px_rgba(59,130,246,0.1)]',
          badge: 'bg-blue-600 text-white border-blue-700',
          title: 'text-slate-900',
        };
    }
  };

  return (
    <div className="min-h-screen bg-white flex flex-col animate-fade-in font-sans">
      {/* Official Header with Reserved Space */}
      <div className="sticky top-0 z-40 bg-white/95 backdrop-blur-md border-b border-slate-100 shadow-sm px-4">
        <div className="pt-safe-top mt-4"></div>
        <div className="h-16 flex items-center justify-between">
          <div className="flex items-center">
            <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 text-slate-800 transition">
              <ChevronLeft size={24} strokeWidth={2.5} />
            </button>
            <div className="ml-2">
              <h1 className="font-black text-slate-900 text-lg tracking-tight">学院通告中心</h1>
              <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest leading-none">ANNOUNCEMENTS</p>
            </div>
          </div>
          <div className="flex items-center space-x-1">
            {isAdmin && (
              <button 
                onClick={() => setIsManageMode(!isManageMode)}
                className={`p-2.5 rounded-full transition-all ${isManageMode ? 'bg-blue-900 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
              >
                <Settings size={20} />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Filter & Add Bar */}
      <div className="p-5 bg-white flex items-center space-x-3">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
          <input 
            type="text" 
            placeholder="搜寻重要通告..." 
            className="w-full bg-slate-100/50 border border-slate-100 rounded-2xl pl-11 pr-4 py-3 text-sm font-bold text-slate-900 focus:ring-4 focus:ring-blue-900/5 focus:border-blue-900 focus:bg-white outline-none transition-all placeholder:text-slate-300"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        {isAdmin && isManageMode && (
          <button 
            onClick={startAdd}
            className="bg-blue-900 text-white p-3 rounded-2xl shadow-xl shadow-blue-900/10 hover:bg-blue-800 transition active:scale-95 shrink-0"
          >
            <Plus size={20} strokeWidth={3} />
          </button>
        )}
      </div>

      {/* Announcements Stream */}
      <div className="flex-1 overflow-y-auto p-5 space-y-5 pb-24 scrollbar-hide">
        {filteredNews.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-200">
            <Bell size={64} strokeWidth={1} className="mb-4 opacity-20" />
            <p className="text-sm font-black tracking-widest uppercase">目前没有任何公开通告</p>
          </div>
        ) : (
          filteredNews.map(item => {
            const isExpanded = expandedId === item.id;
            const styles = getTypeStyles(item.type);
            return (
              <div 
                key={item.id} 
                className={`rounded-[2rem] border transition-all duration-500 overflow-hidden bg-white ${isExpanded ? 'border-blue-100 shadow-2xl scale-[1.02] z-10' : 'border-slate-100 shadow-sm'}`}
              >
                <div 
                  onClick={() => toggleExpand(item.id)}
                  className="p-5 flex items-start cursor-pointer active:bg-slate-50 transition-colors"
                >
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mr-4 shrink-0 transition-all duration-500 ${isExpanded ? 'scale-110 shadow-lg' : ''} ${styles.iconContainer}`}>
                    {item.type === 'Urgent' ? <AlertOctagon size={28} className="animate-pulse" /> : <Bell size={28} strokeWidth={1.5} />}
                  </div>

                  <div className="flex-1 min-w-0 pr-2">
                    <div className="flex items-center space-x-2 mb-1.5">
                      <span className={`text-[8px] font-black px-2 py-0.5 rounded-full border uppercase tracking-wider ${styles.badge}`}>
                        {getTypeText(item.type)}
                      </span>
                      <span className="text-[10px] text-slate-400 font-black">
                        {item.date}
                      </span>
                    </div>
                    <h3 className={`text-base font-black leading-snug tracking-tight ${styles.title} ${isExpanded ? '' : 'line-clamp-2'}`}>
                      {item.title}
                    </h3>
                  </div>

                  <div className="shrink-0 pt-2">
                    {isAdmin && isManageMode ? (
                      <div className="flex space-x-1" onClick={e => e.stopPropagation()}>
                        <button onClick={() => startEdit(item)} className="p-2 text-blue-500 bg-blue-50 rounded-xl transition-all"><Edit2 size={16}/></button>
                      </div>
                    ) : (
                      <div className={`p-1.5 rounded-full transition-all duration-300 ${isExpanded ? 'bg-blue-900 text-white rotate-180 shadow-md' : 'bg-slate-100 text-slate-300'}`}>
                        <ChevronDown size={14} strokeWidth={3} />
                      </div>
                    )}
                  </div>
                </div>

                <div 
                  className={`transition-all duration-500 ease-in-out ${isExpanded ? 'max-h-[2000px] opacity-100' : 'max-h-0 opacity-0'}`}
                >
                  <div className="px-6 pb-6 pt-2 border-t border-slate-50/50">
                    <div className="bg-slate-50/80 rounded-2xl p-5 border border-slate-100 mt-2">
                       <p className="text-[15px] text-slate-700 leading-relaxed whitespace-pre-wrap font-serif">
                          {item.content || <span className="text-slate-400 italic">管理员暂未录入通告详情。</span>}
                       </p>
                    </div>
                    <div className="mt-5 flex justify-between items-center px-1">
                       <p className="text-[9px] text-slate-300 font-black uppercase tracking-[0.3em]">AMAS OFFICIAL</p>
                       {isAdmin && isManageMode && (
                         <button onClick={() => initiateDelete(item.id)} className="flex items-center text-rose-500 font-black text-[10px] bg-rose-50 px-3 py-1 rounded-full border border-rose-100">
                           <Trash2 size={12} className="mr-1" /> 删除通告
                         </button>
                       )}
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Delete Confirmation */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[110] bg-slate-900/60 backdrop-blur-md flex items-center justify-center p-8 animate-fade-in">
          <div className="bg-white w-full max-w-[320px] rounded-[3rem] p-8 shadow-2xl text-center animate-scale-in">
            <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6 border border-rose-100 shadow-inner">
              <AlertTriangle size={36} />
            </div>
            <h3 className="text-xl font-black text-slate-900 mb-2">确定删除？</h3>
            <p className="text-sm text-slate-400 mb-8 font-medium leading-relaxed">删除后该通告将从所有学员的首页消失，且无法撤销。</p>
            <div className="flex flex-col space-y-3">
              <button 
                onClick={confirmDelete}
                className="w-full py-4 bg-rose-600 text-white rounded-2xl font-black text-sm shadow-xl shadow-rose-900/20 active:scale-95 transition-all"
              >
                确认删除
              </button>
              <button 
                onClick={() => { setShowDeleteConfirm(false); setDeletingItemId(null); }}
                className="w-full py-4 bg-slate-50 text-slate-400 rounded-2xl font-black text-sm active:scale-95 transition-all"
              >
                取消
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal View Logic... (rest remains the same) */}
      {showEditModal && (
        <div className="fixed inset-0 z-[100] bg-slate-900/40 backdrop-blur-md flex items-center justify-center p-5 animate-fade-in">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-8 shadow-2xl relative animate-scale-in flex flex-col max-h-[90vh] overflow-hidden border border-white/50">
            <button onClick={() => setShowEditModal(false)} className="absolute top-8 right-8 text-slate-300 hover:text-slate-900 transition-all z-10 p-1 bg-slate-50 rounded-full">
              <X size={20} strokeWidth={3} />
            </button>
            <div className="mb-8">
              <h3 className="text-2xl font-black text-slate-900 tracking-tight leading-none">{editingItem ? '修改详情' : '发布通告'}</h3>
              <p className="text-xs text-slate-400 mt-2 font-black uppercase tracking-widest opacity-60">Announcements System</p>
            </div>
            <form onSubmit={handleAddEditNews} className="space-y-6 flex-1 flex flex-col min-h-0">
               <div className="flex-1 overflow-y-auto space-y-6 pr-2 scrollbar-hide">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">通告标题</label>
                    <input className="w-full bg-slate-100/50 border border-slate-100 rounded-2xl px-5 py-4 text-base text-slate-900 font-black outline-none focus:bg-white focus:ring-4 focus:ring-blue-900/5 focus:border-blue-900 transition-all placeholder:text-slate-300" placeholder="标题..." value={newsForm.title} onChange={e => setNewsForm({ ...newsForm, title: e.target.value })} autoFocus />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">日期</label>
                      <input type="date" className="w-full bg-slate-100/50 border border-slate-100 rounded-2xl px-4 py-3 text-xs text-slate-900 font-bold outline-none" value={newsForm.date} onChange={e => setNewsForm({ ...newsForm, date: e.target.value })} />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">级别</label>
                      <select className="w-full bg-slate-100/50 border border-slate-100 rounded-2xl px-4 py-3 text-xs text-slate-900 font-bold outline-none appearance-none" value={newsForm.type} onChange={e => setNewsForm({ ...newsForm, type: e.target.value as any })}>
                        <option value="Notice">普通通知</option>
                        <option value="Event">学院活动</option>
                        <option value="Urgent">紧急通报</option>
                      </select>
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">内容正文</label>
                    <textarea className="w-full bg-slate-100/50 border border-slate-100 rounded-[2rem] px-5 py-5 text-sm text-slate-700 font-medium outline-none focus:bg-white focus:ring-4 focus:ring-blue-900/5 focus:border-blue-900 transition-all h-60 resize-none leading-relaxed" placeholder="输入内容详情..." value={newsForm.content} onChange={e => setNewsForm({ ...newsForm, content: e.target.value })} />
                  </div>
               </div>
               <div className="pt-4">
                 <button type="submit" className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-black text-base shadow-2xl shadow-blue-900/20 active:scale-95 transition-all">
                    {editingItem ? '确认修改' : '立即发布'}
                 </button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AnnouncementsView;
